@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item"><strong>Total:</strong> @FilteredTasks.Count</span>
        <span class="stat-item"><strong>To Do:</strong> @TodoTasks.Count</span>
        <span class="stat-item"><strong>In Progress:</strong> @InProgressTasks.Count</span>
        <span class="stat-item"><strong>Done:</strong> @DoneTasks.Count</span>
        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @OverdueTasks.Count</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="_searchQuery" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="kanban-board">
        <div class="kanban-column">
            <h3>To Do <span class="badge bg-secondary">@TodoTasks.Count</span></h3>
            @foreach (var task in TodoTasks)
            {
                <TaskCard Task="task" ShowMoveLeft="false" ShowMoveRight="true"
                          OnMoveLeft="() => {}" OnMoveRight="() => MoveRight(task)" />
            }
            @if (_showFormForColumn == "To Do")
            {
                <AddTaskForm OnSave="(t) => SaveTask(t, \"To Do\")" OnCancel="CancelForm" />
            }
            else
            {
                <button class="btn btn-outline-primary btn-sm mt-2" @onclick='() => _showFormForColumn = "To Do"'>Add Task</button>
            }
        </div>

        <div class="kanban-column">
            <h3>In Progress <span class="badge bg-secondary">@InProgressTasks.Count</span></h3>
            @foreach (var task in InProgressTasks)
            {
                <TaskCard Task="task" ShowMoveLeft="true" ShowMoveRight="true"
                          OnMoveLeft="() => MoveLeft(task)" OnMoveRight="() => MoveRight(task)" />
            }
            @if (_showFormForColumn == "In Progress")
            {
                <AddTaskForm OnSave="(t) => SaveTask(t, \"In Progress\")" OnCancel="CancelForm" />
            }
            else
            {
                <button class="btn btn-outline-primary btn-sm mt-2" @onclick='() => _showFormForColumn = "In Progress"'>Add Task</button>
            }
        </div>

        <div class="kanban-column">
            <h3>Done <span class="badge bg-secondary">@DoneTasks.Count</span></h3>
            @foreach (var task in DoneTasks)
            {
                <TaskCard Task="task" ShowMoveLeft="true" ShowMoveRight="false"
                          OnMoveLeft="() => MoveLeft(task)" OnMoveRight="() => {}" />
            }
            @if (_showFormForColumn == "Done")
            {
                <AddTaskForm OnSave="(t) => SaveTask(t, \"Done\")" OnCancel="CancelForm" />
            }
            else
            {
                <button class="btn btn-outline-primary btn-sm mt-2" @onclick='() => _showFormForColumn = "Done"'>Add Task</button>
            }
        </div>
    </div>
}

@code {
    private List<TaskItem> _tasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchQuery = string.Empty;
    private string? _showFormForColumn;

    private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(_searchQuery)
        ? _tasks
        : _tasks.Where(t => t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == "Done").ToList();
    private List<TaskItem> OverdueTasks => FilteredTasks.Where(t => t.DueDate < DateTime.Today && t.Status != "Done").ToList();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    private async Task MoveLeft(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex > 0)
        {
            var newStatus = Statuses[currentIndex - 1];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = _tasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
                _tasks[index] = task with { Status = newStatus };
        }
    }

    private async Task MoveRight(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex < Statuses.Length - 1)
        {
            var newStatus = Statuses[currentIndex + 1];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = _tasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
                _tasks[index] = task with { Status = newStatus };
        }
    }

    private async Task SaveTask((string Title, string Assignee, string Priority, DateTime DueDate) formData, string status)
    {
        var newTask = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
        _tasks.Add(newTask with { Status = status });
        _showFormForColumn = null;
    }

    private void CancelForm()
    {
        _showFormForColumn = null;
    }
}

